#include &lt;stdio.h&gt;

using ull = unsigned long long int;

ull get_out(ull base, ull power)
{
    const ull MAX = 1'000'000'000ULL + 1;
    ull ret = 1;

    while (power != 0) {
        if (ret &gt; MAX) {
            return MAX;
        }

        if ((power % 2) == 1) {
            ret *= base;
            --power;
            continue;
        }

        power &gt;&gt;= 1;
        if (base * base &gt; MAX) {
            return MAX;
        }
        base *= base;
    }

    return ret;
}

ull get_out(ull base, ull power, ull mod)
{
    ull ret = base;

    if (power == 0) {
        return 1;
    } else if ((power % 2) == 1) {
        return ((ret % mod) * get_out(base, power - 1, mod)) % mod;
    } else {
        return (get_out((base * base) % mod, power &gt;&gt; 1, mod) % mod);
    }

    return ret;
}

int main(void)
{
    int t;
    scanf("%d", &t);
    while (t--) {
        ull x, y, z;
        scanf("%llu%llu%llu", &x, &y, &z);

        ull cmp = get_out(x, y);
        ull out = get_out(x, y, z * 1000);
        ull integer = out / z;
        ull decimal = out % z;
        decimal *= 1000;
        decimal /= z;
        if (cmp == out) {
            printf("%llu.%03llu\n", integer, decimal);
        } else {
            printf("%03llu.%03llu\n", integer, decimal);
        }
    }
}

2. 자료구조 설계
그룹마다 독립적인 해시 테이블을 둔다.
struct Event {
    char name[MAX_NAME_LEN];
    int  h_key;            // 슬롯 상태 겸 인덱스
    int  n_participants;
    int  participant[5];
} event[MAX_GRP][MAX_HKEY];

해시 함수: djb2. 매 스텝 % MAX_HKEY로 누적해 [0, MAX_HKEY) 범위의 슬롯 인덱스를 얻는다.
충돌 처리: open addressing + 선형 탐사(linear probing).
유저 측 자료구조: 각 유저는 자신이 속한 일정 목록을 {gid, slot index, is_master}로 들고 있다.

여기서 중요한 설계 관찰이 하나 있다. 유저는 일정을 가리킬 때 슬롯 인덱스를 직접 저장하므로, “유저 → 일정” 조회(find_evt_idx)는 해시 탐사를 전혀 거치지 않는다. 해시 테이블의 탐사가 실제로 쓰이는 곳은 오직 addEvent 내부의 find / add뿐이다. 즉 버그가 숨을 수 있는 표면은 find/add 단 두 함수로 좁혀진다.






Note



디버깅에 들어가기 전에 “해시가 실제로 관여하는 코드 경로”를 먼저 좁혀두면, 원인 후보를 크게 줄일 수 있다. 자료구조가 인덱스를 직접 들고 있는 부분과 해시로 탐색하는 부분을 분리해서 보는 습관이 도움이 된다.

