#define MAX_GRP         (100)
#define MAX_USER        (1000)
#define MAX_NAME_LEN    (16)
#define MAX_HKEY        (1007)

void mstrcpy(char dst[], const char src[]) {
    int c = 0;
    while ((dst[c] = src[c]) != 0) ++c;
}

int mstrcmp(const char str1[], const char str2[]) {
    int c = 0;
    while (str1[c] != 0 && str1[c] == str2[c]) ++c;
    return str1[c] - str2[c];
}

unsigned long hash(const char *str) {
    unsigned long hash = 5381;
    int c;
    while (c = *str++) {
        hash = (((hash &lt;&lt; 5) + hash) + c) % MAX_HKEY;
    }
    return hash % MAX_HKEY;
}

struct Event {
    char name[MAX_NAME_LEN];
    int  h_key;
    int  n_participants;
    int  participant[5];

    void delete_pid(int pid) {
        int i = 0;
        for (; i &lt; n_participants; ++i) {
            if (participant[i] == pid) break;
        }
        participant[i] = participant[n_participants - 1];
        --n_participants;
    }

    // key_designated == -1 : EMPTY (전체 초기화)
    // key_designated == -2 : DELETED (tombstone)
    void init(int key_designated = -1) {
        name[0] = 0;
        h_key   = key_designated;
        n_participants = 0;
    }

    void add_participant(int pid) {
        participant[n_participants++] = pid;
    }
} event[MAX_GRP][MAX_HKEY];

// EMPTY(h_key == -1)에서만 멈추고, DELETED(-2)는 통과한다.
Event* find(int gid, const char *key) {
    unsigned long h = hash(key);
    int cnt = MAX_HKEY;
    while (event[gid][h].h_key != -1 && cnt--) {
        if (mstrcmp(event[gid][h].name, key) == 0) {
            return &event[gid][h];
        }
        h = (h + 1) % MAX_HKEY;
    }
    return nullptr;
}

// DELETED 슬롯(name[0] == 0)을 재활용한다.
// 반드시 find가 nullptr을 반환한 직후에만 호출되어야 한다.
Event* add(int gid, const char *key) {
    unsigned long h = hash(key);
    while (event[gid][h].name[0] != 0) {
        if (mstrcmp(event[gid][h].name, key) == 0) {
            return nullptr;
        }
        h = (h + 1) % MAX_HKEY;
    }
    mstrcpy(event[gid][h].name, key);
    event[gid][h].h_key = h;
    return &event[gid][h];
}

struct User {
    int n_events;
    struct {
        int  key;
        int  gid;
        bool is_master;
    } event_info[100];

    void init() {
        n_events = 0;
    }

    void add_event(int gid, int event_key, bool master_flag) {
        event_info[n_events].key       = event_key;
        event_info[n_events].gid       = gid;
        event_info[n_events].is_master = master_flag;
        ++n_events;
    }

    void delete_event(int evt_id) {
        event_info[evt_id] = event_info[n_events - 1];
        --n_events;
    }

    int find_evt_idx(char ename[]) {
        for (int i = 0; i &lt; n_events; ++i) {
            auto evt = &event[event_info[i].gid][event_info[i].key];
            if (mstrcmp(evt-&gt;name, ename) != 0) continue;
            return i;
        }
        return -1;
    }
} user[MAX_USER];

void init() {
    for (int i = 0; i &lt; MAX_USER; ++i) {
        user[i].init();
    }
    for (int i = 0; i &lt; MAX_GRP; ++i) {
        for (int j = 0; j &lt; MAX_HKEY; ++j) {
            event[i][j].init();
        }
    }
}

void addEvent(int uid, char ename[], int groupid) {
    bool is_master = false;
    auto evt = find(groupid, ename);
    if (evt == nullptr) {
        evt = add(groupid, ename);
        is_master = true;
    }
    evt-&gt;add_participant(uid);
    user[uid].add_event(groupid, evt-&gt;h_key, is_master);
}

int deleteEvent(int uid, char ename[]) {
    int evt_id = user[uid].find_evt_idx(ename);
    if (evt_id == -1) {
        return 0;
    }

    int cnt = 1;
    auto  target = user[uid].event_info[evt_id];
    auto& evt    = event[target.gid][target.key];

    user[uid].delete_event(evt_id);

    if (target.is_master == true) {
        for (int i = 1; i &lt; evt.n_participants; ++i) {
            int pid      = evt.participant[i];
            int nevt_id  = user[pid].find_evt_idx(ename);
            user[pid].delete_event(nevt_id);
            ++cnt;
        }
        evt.init(-2);   // tombstone
    }
    else {
        evt.delete_pid(uid);
    }
    return cnt;
}

int changeEvent(int uid, char ename[], char cname[]) {
    int evt_id = user[uid].find_evt_idx(ename);
    if (evt_id == -1) {
        return 0;
    }

    int cnt = 1;
    auto  target = user[uid].event_info[evt_id];
    auto& evt    = event[target.gid][target.key];

    user[uid].delete_event(evt_id);
    addEvent(uid, cname, target.gid);

    if (target.is_master == true) {
        for (int i = 1; i &lt; evt.n_participants; ++i) {
            int pid     = evt.participant[i];
            int nevt_id = user[pid].find_evt_idx(ename);
            user[pid].delete_event(nevt_id);
            addEvent(pid, cname, target.gid);
            ++cnt;
        }
        evt.init(-2);   // tombstone
    }
    else {
        evt.delete_pid(uid);
    }
    return cnt;
}

int getCount(int uid) {
    return user[uid].n_events;
}

6 \(-1\) 판정
§3.2에서 보았듯이, 인접한 원소 중 같은 MSB를 가지는 쌍이 하나도 없으면 답은 \(-1\)이다.
bool all_msb_distinct = true;
for (int i = 2; i &lt;= n; ++i) {
    if ((31 - __builtin_clz(a[i])) == (31 - __builtin_clz(a[i-1]))) {
        all_msb_distinct = false;
        break;
    }
}
if (all_msb_distinct) { puts("-1"); continue; }






Tip대안 판정: 전체 XOR의 popcount



실전에서 popcount(a[1] ^ a[2] ^ ... ^ a[n]) == n 조건으로 판정하는 풀이도 AC를 받는다. 이는 모든 MSB가 서로 다를 때 XOR이 비트를 보존하는 성질에 의존하는데, 엄밀한 동치 증명은 쉽지 않으므로 MSB 직접 비교가 더 안전하다.

7 전체 풀이 코드
#include &lt;stdio.h&gt;

int a[100001];
int px[100001];

int main(void)
{
    int t;
    scanf("%d", &t);
    while (t--) {
        int n;
        scanf("%d", &n);
        px[0] = 0;
        for (int i = 1; i &lt;= n; ++i) {
            scanf("%d", &a[i]);
            px[i] = px[i - 1] ^ a[i];
        }

        // Case 1: N &gt;= 61 → 비둘기집 원리로 답 = 1
        if (n &gt;= 61) {
            puts("1");
            continue;
        }

        // Case 2: 모든 인접 MSB가 다르면 → 답 = -1
        bool all_distinct = true;
        for (int i = 2; i &lt;= n; ++i) {
            if ((31 - __builtin_clz(a[i])) == (31 - __builtin_clz(a[i - 1]))) {
                all_distinct = false;
                break;
            }
        }
        if (all_distinct) {
            puts("-1");
            continue;
        }

        // Case 3: N &lt;= 60 → O(N^3) 브루트포스
        int best = 100000;
        for (int i = 1; i &lt;= n; ++i) {
            for (int j = i; j &lt;= n; ++j) {
                int L = px[j] ^ px[i - 1];
                for (int k = j + 1; k &lt;= n; ++k) {
                    int R = px[k] ^ px[j];
                    if (L &gt; R) {
                        int cost = k - i - 1;
                        if (cost &lt; best) {
                            best = cost;
                        }
                        if (best == 1) {
                            goto done;
                        }
                    }
                }
            }
        }
        done:
        printf("%d\n", best);
    }
    return 0;
}

