#include &lt;stdio.h&gt;

using ll = long long int;

int main(void)
{
    int t;
    scanf("%d", &t);
    while(t--)
    {
        int n;
        scanf("%d", &n);

        int a[50];
        for(int i = 0; i &lt; n; ++i) scanf("%d", &a[i]), a[i] &lt;&lt;= 1;

        bool is_inf = false;
        for(int i = 0; i &lt; n - 1; ++i)
        {
            if(a[i] == a[i + 1])
            {
                is_inf = true;
                break;
            }
        }
        if(is_inf)
        {
            printf("-1\n");
            continue;
        }

        int cand_scaled[99];
        for(int i = 0; i &lt; n; ++i) cand_scaled[i] = a[i];

        // 삽입 정렬
        for(int j = 1; j &lt; n; ++j)
        {
            int key = cand_scaled[j];
            int i = j - 1;
            while(i &gt;= 0 && cand_scaled[i] &gt; key)
            {
                cand_scaled[i + 1] = cand_scaled[i];
                --i;
            }
            cand_scaled[i + 1] = key;
        }

        // 정렬된 고유값 사이 중간점 후보
        for(int i = 0; i &lt; n - 1; ++i)
            cand_scaled[i + n] = ((ll)cand_scaled[i] + cand_scaled[i + 1]) / 2;

        int _max_val = -1;
        int iter = (2 * n) - 1;

        auto get_cnt_root = [&a, n](int y0) -&gt; int
        {
            int cnt = 0;
            for(int i = 0; i &lt; n - 1; ++i)
            {
                int low  = (a[i] &lt; a[i + 1]) ? a[i] : a[i + 1];
                int high = (a[i] &lt; a[i + 1]) ? a[i + 1] : a[i];

                bool cond =
                    ((a[i] &lt; a[i + 1]) && (y0 &gt;= low && y0 &lt; high)) ||
                    ((a[i] &gt; a[i + 1]) && (y0 &gt; low && y0 &lt;= high));

                if(cond) ++cnt;
            }
            if(y0 == a[n - 1]) ++cnt;
            return cnt;
        };

        for(int i = 0; i &lt; iter; ++i)
        {
            auto curr = get_cnt_root(cand_scaled[i]);
            _max_val = (_max_val &gt; curr) ? _max_val : curr;
        }

        printf("%d\n", _max_val);
    }
}

삽입 정렬 템플릿
&lt;algorithm&gt; 헤더 사용이 제한된 환경에서는 삽입 정렬을 직접 구현해야 한다. 핵심 두 줄의 패턴을 기억하자: 밀 때 [i+1] = [i], 넣을 때 [i+1] = key.
for(int j = 1; j &lt; n; ++j)
{
    int key = arr[j];
    int i = j - 1;
    while(i &gt;= 0 && arr[i] &gt; key)
    {
        arr[i + 1] = arr[i];   // 큰 원소를 오른쪽으로 밀기
        --i;
    }
    arr[i + 1] = key;          // 빈 자리에 삽입
}

6 코드
#include &lt;stdio.h&gt;
#include &lt;unordered_map&gt;

using ull = unsigned long long int;
int n;
ull x, a[60], ub[60];
std::unordered_map&lt;ull, ull&gt; dp[60];

ull solve(int idx, ull mask)
{
    if (idx &lt; 0) return 1;
    if (dp[idx].find(mask) != dp[idx].end()) return dp[idx][mask];
    ull& ans = dp[idx][mask] = 0;

    ull constraints = mask;
    if (idx &lt; n) {
        if (ub[idx] &lt; (1ULL &lt;&lt; (idx + 1))) {
            constraints |= (1ULL &lt;&lt; idx);
        }
    }

    for (int val = 0; val &lt;= 1; ++val) {
        bool is_valid = true;
        ull new_mask = 0x00;

        for (int c = 0; c &lt; n; ++c) {
            if ((constraints &gt;&gt; c) & 1) {
                int req_bit = ((ub[c] &gt;&gt; idx) & 1);
                if (val &gt; req_bit) {
                    is_valid = false;
                    break;
                }
                if (val == req_bit) {
                    new_mask |= (1LL &lt;&lt; c);
                }
            }
        }
        if (is_valid) {
            ans += solve(idx - 1, new_mask);
        }
    }

    return ans;
}

int main(void)
{
    int t;
    scanf("%d", &t);
    while (t--) {
        ull s = 0;
        scanf("%d %llu", &n, &x);
        for (int i = 0; i &lt; 60; ++i) dp[i].clear();
        for (int i = 0; i &lt; n; ++i) {
            scanf("%llu", &a[i]);
            s += a[i] &lt;&lt; i;
            ub[i] = s / x;
        }

        printf("%llu\n", solve(59, (1ULL &lt;&lt; n - 1)));
    }
}

2.3 토큰의 선형 조합과 .z 표기
뉴런의 선형 조합은 스칼라 가중합이다:
x_\text{out} = \sum_{i=1}^N w_i \, x_{\text{in}_i}
토큰의 선형 조합도 본질은 같지만, 단위가 벡터이므로 표기가 달라진다:
t_\text{out}.\mathbf{z} = \sum_{i=1}^N w_i \, t_{\text{in}_i}.\mathbf{z}






Important.z 표기의 의미



.z는 토큰 벡터의 특정 차원(element)을 가리키는 인덱싱 표기다. 즉 위 수식은 “출력 토큰의 z번째 차원은, 입력 토큰들의 z번째 차원의 가중합이다” 라는 뜻이며, 이는 모든 차원에 대해 동일한 가중치 w_i가 적용된다는 사실을 명시적으로 드러낸다.
벡터 표기로 다시 쓰면 단순하다: \mathbf{t}_\text{out} = \sum_{i=1}^N w_i \, \mathbf{t}_{\text{in}_i}


이 element-wise 동일 가중치 구조가 바로 attention의 Value 가중합과 정확히 일치한다.

5.6 Indicator random variable 정의
다음 지시변수를 정의하자.
\[
X_{ij} = I\{A[j] \text{ falls in bucket } i\}
\]
즉,
\[
X_{ij} =
\begin{cases}
1 & \text{if } A[j] \text{가 bucket } i \text{에 들어가면}, \\
0 & \text{otherwise.}
\end{cases}
\]
그러면 bucket \(i\)의 원소 수는 \[
n_i = \sum_{j=0}^{n-1} X_{ij}
\] 이다.

12.2 행렬 관점
일반 Conv를 행렬 곱으로 표현:

\mathbf{y} = \mathbf{C}\mathbf{x}

여기서 \mathbf{C}는 Toeplitz 구조의 convolution matrix.
Transposed Convolution:

\mathbf{y} = \mathbf{C}^\top \mathbf{x}

전치행렬을 곱하는 것이지, 역행렬을 곱하는 것이 아니다.

\mathbf{C}^\top \neq \mathbf{C}^{-1}

8.1 Skip connections through time
ResNet/DenseNet의 시간축 버전. 멀리 떨어진 시점을 직접 연결.
h^{(t)} = f(h^{(t-1)}, x^{(t)}) + h^{(t-d)}

8.2 Leaky units
\mu^{(t)} \leftarrow \alpha\, \mu^{(t-1)} + (1-\alpha)\, v^{(t)}
지수이동평균(EMA) 형태. \alpha가 1에 가까우면 천천히 변하는 long-term 정보, 0에 가까우면 빠른 변화 추적. 무선통신의 EMA 기반 채널 추정과 동일한 구조다.

