#include &lt;bits/stdc++.h&gt;
using namespace std;
typedef long long ll;

const int MAXP = 100001;  // prices in [1, MAXP-1]

struct Node {
    ll liters;
    ll cost;
};
Node seg[4 * MAXP];

void update(int node, int l, int r, int idx, ll dl) {
    if (l == r) {
        seg[node].liters += dl;
        seg[node].cost   += dl * (ll)l;   // l == price at the leaf
        return;
    }
    int mid = (l + r) &gt;&gt; 1;
    if (idx &lt;= mid) {
        update(node &lt;&lt; 1, l, mid, idx, dl);
    } else {
        update(node &lt;&lt; 1 | 1, mid + 1, r, idx, dl);
    }
    seg[node].liters = seg[node &lt;&lt; 1].liters + seg[node &lt;&lt; 1 | 1].liters;
    seg[node].cost   = seg[node &lt;&lt; 1].cost   + seg[node &lt;&lt; 1 | 1].cost;
}

// min cost to obtain exactly L liters from active liquids; -1 if pool insufficient
ll query(int node, int l, int r, ll L) {
    if (seg[node].liters &lt; L) {
        return -1;
    }
    if (l == r) {
        return L * (ll)l;
    }
    int mid = (l + r) &gt;&gt; 1;
    if (seg[node &lt;&lt; 1].liters &gt;= L) {
        return query(node &lt;&lt; 1, l, mid, L);
    } else {
        return seg[node &lt;&lt; 1].cost
             + query(node &lt;&lt; 1 | 1, mid + 1, r, L - seg[node &lt;&lt; 1].liters);
    }
}

int main() {
    int TC;
    scanf("%d", &TC);
    while (TC--) {
        int n, m;
        scanf("%d %d", &n, &m);

        vector&lt;array&lt;int, 3&gt;&gt; liq(n);  // {d, p, l}
        for (int i = 0; i &lt; n; ++i) {
            scanf("%d %d %d", &liq[i][0], &liq[i][1], &liq[i][2]);
        }
        sort(liq.begin(), liq.end(),
             [](const array&lt;int,3&gt;& a, const array&lt;int,3&gt;& b) {
                 return a[0] &gt; b[0];   // taste descending
             });

        vector&lt;ll&gt; G(m), L(m);
        for (int j = 0; j &lt; m; ++j) {
            scanf("%lld %lld", &G[j], &L[j]);
        }

        // Binary search: smallest k in [0, n-1] s.t. feasible(top-(k+1)).
        // hi = n is the "infeasible" sentinel.
        vector&lt;int&gt; lo(m, 0), hi(m, n);

        while (true) {
            vector&lt;vector&lt;int&gt;&gt; bucket(n + 1);
            bool active = false;
            for (int j = 0; j &lt; m; ++j) {
                if (lo[j] &lt; hi[j]) {
                    int mid = (lo[j] + hi[j]) &gt;&gt; 1;
                    bucket[mid].push_back(j);
                    active = true;
                }
            }
            if (!active) {
                break;
            }

            memset(seg, 0, sizeof(seg));

            for (int k = 0; k &lt; n; ++k) {
                int p   = liq[k][1];
                int lit = liq[k][2];
                update(1, 1, MAXP - 1, p, lit);

                for (int j : bucket[k]) {
                    ll c = query(1, 1, MAXP - 1, L[j]);
                    if (c != -1 && c &lt;= G[j]) {
                        hi[j] = k;
                    } else {
                        lo[j] = k + 1;
                    }
                }
            }
        }

        for (int j = 0; j &lt; m; ++j) {
            if (j &gt; 0) {
                putchar(' ');
            }
            int k = lo[j];
            if (k &gt;= n) {
                printf("-1");
            } else {
                printf("%d", liq[k][0]);
            }
        }
        putchar('\n');
    }
    return 0;
}

